import{_ as e,o as d,c as r,a5 as a}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"求职英语证据卡：从岗位描述到陌生追问","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/interview-evidence.zh.md","filePath":"public/downloads/worksheets/interview-evidence.zh.md","lastUpdated":1795488252000}'),i={name:"public/downloads/worksheets/interview-evidence.zh.md"};function h(l,t,n,b,o,s){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="求职英语证据卡-从岗位描述到陌生追问" tabindex="-1">求职英语证据卡：从岗位描述到陌生追问 <a class="header-anchor" href="#求职英语证据卡-从岗位描述到陌生追问" aria-label="Permalink to &quot;求职英语证据卡：从岗位描述到陌生追问&quot;">​</a></h1><p>这张卡不判断你“适不适合海外工作”，也不承诺通过面试。它回答一个更具体的问题：<strong>在当前岗位和流程下，我能否把真实能力用英语完成交付？</strong></p><p>复制到私有笔记。岗位描述、招聘邮件、take-home task、公司代码、客户信息和面试录音可能含有保密或个人信息；只保存你有权使用的最少内容，录音前取得必要同意。</p><h2 id="_1-岗位与流程" tabindex="-1">1. 岗位与流程 <a class="header-anchor" href="#_1-岗位与流程" aria-label="Permalink to &quot;1. 岗位与流程&quot;">​</a></h2><p>岗位名称与公开链接：<br> 申请截止或面试日期：<br> 工作方式：远程 / 混合 / 现场<br> 主要时区与协作方式：<br> 已知面试阶段：<br> 岗位明确语言要求：<br> 当前仍未知的招聘规则：</p><h2 id="_2-岗位语言地图" tabindex="-1">2. 岗位语言地图 <a class="header-anchor" href="#_2-岗位语言地图" aria-label="Permalink to &quot;2. 岗位语言地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>岗位事实</th><th>语言任务</th><th>当前证据</th><th>风险等级</th><th>两周内是否补证据</th></tr></thead><tbody><tr><td></td><td>招聘沟通 / 项目说明 / 技术追问 / 行为问题 / 异步写作 / 客户沟通</td><td></td><td>高 / 中 / 低</td><td></td></tr></tbody></table><p>已经能独立完成：<br> 需要准备才能完成：<br> 依赖提示或翻译：<br> 没有样本：<br> 只补的一个最高风险缺口：</p><h2 id="_3-完整基线" tabindex="-1">3. 完整基线 <a class="header-anchor" href="#_3-完整基线" aria-label="Permalink to &quot;3. 完整基线&quot;">​</a></h2><p>日期：<br> 准备时间：<br> 可见稿件：无 / 提纲 / 逐字稿<br> 工具：无 / 词典 / 字幕 / AI / 其他<br> 录音与文本位置：</p><table tabindex="0"><thead><tr><th>阶段</th><th style="text-align:right;">时间</th><th>完成标准</th><th>独立结果</th><th>主要错误</th></tr></thead><tbody><tr><td>岗位相关自我介绍</td><td style="text-align:right;">2 分钟</td><td>现在、证据、方向清楚</td><td></td><td></td></tr><tr><td>项目说明</td><td style="text-align:right;">5 分钟</td><td>背景、责任、取舍、结果、未知</td><td></td><td></td></tr><tr><td>陌生追问</td><td style="text-align:right;">3 题</td><td>理解、回答或主动澄清</td><td></td><td></td></tr><tr><td>异步更新</td><td style="text-align:right;">20 分钟</td><td>进展、证据、风险、下一步、负责人</td><td></td><td></td></tr><tr><td>互动修复</td><td style="text-align:right;">1 次</td><td>重复/确认/思考时间/未知边界</td><td></td><td></td></tr></tbody></table><h2 id="_4-错误地图" tabindex="-1">4. 错误地图 <a class="header-anchor" href="#_4-错误地图" aria-label="Permalink to &quot;4. 错误地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>片段/问题</th><th>类型</th><th>它如何影响任务</th><th>下一次只测试什么</th></tr></thead><tbody><tr><td></td><td>内容 / 检索 / 听力 / 组织 / 互动 / 准确</td><td></td><td></td></tr></tbody></table><p>最大问题其实不是英语的部分：<br> 持续改变关键意思的语言错误：<br> 最值得保留的修复动作：</p><h2 id="_5-真实故事库" tabindex="-1">5. 真实故事库 <a class="header-anchor" href="#_5-真实故事库" aria-label="Permalink to &quot;5. 真实故事库&quot;">​</a></h2><p>每个故事只保存六行，不写逐字稿：</p><p>故事名称：<br> 场景与必须完成的任务：<br> 我的具体责任：<br> 关键动作与取舍：<br> 结果、代价和未知：<br> 如果重来会改变什么：<br> 证据位置：</p><table tabindex="0"><thead><tr><th>故事</th><th>可回答的问题</th><th>陌生追问后是否仍可调用</th><th>事实/隐私检查</th></tr></thead><tbody><tr><td></td><td>解决问题 / 失败 / 冲突 / 决策 / 反馈 / 停止</td><td>是 / 否</td><td></td></tr></tbody></table><h2 id="_6-听力与修复" tabindex="-1">6. 听力与修复 <a class="header-anchor" href="#_6-听力与修复" aria-label="Permalink to &quot;6. 听力与修复&quot;">​</a></h2><p>没有听清的原问题：<br> 我请求重复或确认的句子：<br> 对方重述后我理解的意思：<br> 我的回答：<br> 最后如何确认双方理解：</p><table tabindex="0"><thead><tr><th>修复能力</th><th style="text-align:right;">首版 0–2</th><th style="text-align:right;">第 7 天 0–2</th><th>证据</th></tr></thead><tbody><tr><td>请求重复具体部分</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>确认问题范围</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>争取思考时间</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>承认未知并给验证步骤</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>总结共识与下一步</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><h2 id="_7-异步写作样本" tabindex="-1">7. 异步写作样本 <a class="header-anchor" href="#_7-异步写作样本" aria-label="Permalink to &quot;7. 异步写作样本&quot;">​</a></h2><p>Context:<br> Completed:<br> Evidence:<br> Blocked / risk:<br> Decision needed:<br> Owner and next update:</p><p>请一位读者回答：</p><p>发生了什么：<br> 什么需要决定：<br> 谁在什么时候继续：<br> 哪一句需要猜测：</p><h2 id="_8-ai-与诚信记录" tabindex="-1">8. AI 与诚信记录 <a class="header-anchor" href="#_8-ai-与诚信记录" aria-label="Permalink to &quot;8. AI 与诚信记录&quot;">​</a></h2><p>工具与日期：<br> 它模拟的角色：<br> 我先提交的独立版本：<br> 它提出的三个问题：<br> 我采纳/拒绝的反馈与理由：<br> 关闭工具后的平行问题结果：<br> 必须披露或禁止 AI 的阶段：<br> 没有上传的保密/个人信息：</p><p>不要虚构经历、数字和职责。未经明确允许，不在真实面试中使用隐蔽实时提示。</p><h2 id="_9-十四天比较" tabindex="-1">9. 十四天比较 <a class="header-anchor" href="#_9-十四天比较" aria-label="Permalink to &quot;9. 十四天比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间点</th><th>条件</th><th style="text-align:right;">任务完成</th><th style="text-align:right;">理解/修复</th><th style="text-align:right;">组织/检索</th><th style="text-align:right;">异步写作</th><th>证据</th></tr></thead><tbody><tr><td>第 1 天基线</td><td>无稿、无 AI</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>即时修订</td><td>看过反馈</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>第 7 天复测</td><td>平行问题、撤掉原答案</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>第 14 天迁移</td><td>新面试者/顺序/岗位问题</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>每项 0–2：<code>0=未完成</code>，<code>1=部分完成或依赖提示</code>，<code>2=在当前条件下完成</code>。只用于同一人的同类任务比较。</p><h2 id="_10-当前岗位门槛" tabindex="-1">10. 当前岗位门槛 <a class="header-anchor" href="#_10-当前岗位门槛" aria-label="Permalink to &quot;10. 当前岗位门槛&quot;">​</a></h2><ul><li>[ ] 至少三个真实故事可以在不同问法下调用；</li><li>[ ] 能完成招聘筛选、项目说明和陌生追问；</li><li>[ ] 没听清时会确认，不用猜测维持流畅；</li><li>[ ] 关键语言错误不持续改变意思；</li><li>[ ] 能写一份可继续工作的异步更新；</li><li>[ ] 知道保密、录音和 AI 使用边界；</li><li>[ ] 能承认未知，并说明验证方法；</li><li>[ ] 面试设备、时区和环境已检查。</li></ul><p>当前最支持：立即投递并继续练习 / 先补一个高风险缺口 / 暂缓该岗位<br> 依据：<br> 仍不能推出的结论：<br> 下一项最小任务：<br> 下次复查日期：</p><h2 id="_11-面试后关账" tabindex="-1">11. 面试后关账 <a class="header-anchor" href="#_11-面试后关账" aria-label="Permalink to &quot;11. 面试后关账&quot;">​</a></h2><p>实际问题：<br> 理解正确的证据：<br> 有效的澄清：<br> 没有回答问题的故事：<br> 成功迁移的结构：<br> 并非英语造成的困难：<br> 招聘方原话反馈：<br> 下一次只改变的变量：<br> 停止准备的内容：</p><p>相关章节：<a href="https://byoungd.github.io/up/threads/part-1/8-job-search-english" target="_blank" rel="noreferrer">求职英语篇：把能力带进面试与远程协作</a> ｜ <a href="https://byoungd.github.io/up/templates/speaking-evidence" target="_blank" rel="noreferrer">口语证据卡</a> ｜ <a href="https://byoungd.github.io/up/templates/writing-evidence" target="_blank" rel="noreferrer">写作证据卡</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/interview-evidence" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-09-02。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',39)])])}const c=e(i,[["render",h]]);export{p as __pageData,c as default};
